<template>
	<view class="redirect-page">
		<text>正在打开我的动态...</text>
	</view>
</template>

<script>
export default {
	onLoad(query = {}) {
		const params = Object.keys(query)
			.map((key) => `${encodeURIComponent(key)}=${encodeURIComponent(query[key] || '')}`)
			.join('&');
		uni.redirectTo({
			url: `/pages/myRecords/index${params ? `?${params}` : ''}`,
			fail: () => uni.switchTab({ url: '/pages/profile/index' })
		});
	}
};
</script>

<style scoped>
.redirect-page {
	display: flex;
	align-items: center;
	justify-content: center;
	min-height: 100vh;
	background: #fffafd;
	color: #9b8d95;
	font-size: 24rpx;
}
</style>
